// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 deposit, uint256 ownerInitialBalance) public {
        deposit = bound(deposit, 1, 1 ether);
        ownerInitialBalance = bound(ownerInitialBalance, 1, 10 ether);

        RevertingOwner badOwner = new RevertingOwner();

        vm.deal(address(badOwner), ownerInitialBalance);

        address funder = address(0xABCD);
        vm.deal(funder, deposit);
        vm.prank(funder);
        (bool s,) = address(c).call{value: deposit}("");
        require(s);

        assert(address(c).balance == deposit);

        vm.prank(address(badOwner));
        MultiplicatorX4 c2 = new MultiplicatorX4();

        vm.deal(funder, deposit);
        vm.prank(funder);
        (bool s2,) = address(c2).call{value: deposit}("");
        require(s2);
        assert(address(c2).balance == deposit);

        bool ok;
        vm.prank(address(badOwner));
        try c2.withdraw{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c2).balance == 0);
        } else {
            assertTrue(address(c2).balance == deposit);
        }
    }
}

contract RevertingOwner {
    receive() external payable {
        revert("no receive");
    }
    fallback() external payable {
        revert("no fallback");
    }
}
